def forecast(x, timer, p, k):
    for _ in range(k):
        if x < 0:
            x = 8
        elif x > 8:
            x = 0
        elif abs(p) < 1:
            x += int(1/p)
        else:
            timer -= 1
            if timer == -1:
                timer += abs(p)
                x += sign(p)
    return x

